using WeTextProcessing.NET;

namespace WeTextProcessing.Tests
{
    /// <summary>
    /// Pins WeTextProcessing.NET output to the Python WeTextProcessing package, line by line.
    /// Each TestData/*.tsv file holds "input\texpected" pairs generated by the Python
    /// implementation (see TestData/generate_golden.py) from its official test corpus.
    /// </summary>
    [TestClass]
    public class GoldenCorpusTests
    {
        private static readonly Dictionary<string, WetextProcessor> Processors = new();

        [ClassInitialize]
        public static void ClassInitialize(TestContext _)
        {
            Processors["zh_tn"] = new WetextProcessor(WetextLanguage.Chinese, WetextMode.TextNormalization);
            Processors["zh_itn"] = new WetextProcessor(WetextLanguage.Chinese, WetextMode.InverseTextNormalization);
            Processors["en_tn"] = new WetextProcessor(WetextLanguage.English, WetextMode.TextNormalization);
            Processors["en_itn"] = new WetextProcessor(WetextLanguage.English, WetextMode.InverseTextNormalization);
        }

        [ClassCleanup]
        public static void ClassCleanup()
        {
            foreach (var processor in Processors.Values)
            {
                processor.Dispose();
            }
            Processors.Clear();
        }

        [TestMethod]
        [DataRow("zh_tn")]
        [DataRow("zh_itn")]
        [DataRow("en_tn")]
        [DataRow("en_itn")]
        public void Normalize_MatchesPythonGoldenCorpus(string corpus)
        {
            var path = Path.Combine(AppContext.BaseDirectory, "TestData", $"{corpus}.tsv");
            var lines = File.ReadAllLines(path);
            Assert.AreNotEqual(0, lines.Length, $"Golden corpus is empty: {path}");

            var processor = Processors[corpus];
            var failures = new List<string>();
            foreach (var line in lines)
            {
                if (line.Length == 0) continue;
                var parts = line.Split('\t');
                Assert.AreEqual(2, parts.Length, $"Malformed golden line: {line}");

                var (input, expected) = (parts[0], parts[1]);
                var actual = processor.Normalize(input);
                if (actual != expected)
                {
                    failures.Add($"input: {input}\n  expected: {expected}\n  actual:   {actual}");
                }
            }

            if (failures.Count > 0)
            {
                Assert.Fail(
                    $"{corpus}: {failures.Count}/{lines.Length} mismatches against Python golden corpus:\n" +
                    string.Join("\n", failures.Take(20)));
            }
        }
    }
}
